    {"type": "choice", "q": "Trong mặt phẳng tọa độ Oxy, đường thẳng có hệ số góc bằng 2 và đi qua điểm A(2; 1) có phương trình là:", "options": ["y = 2x + 5", "y = -2x - 3", "y = -2x + 3", "y = 2x - 3"], "answer": "y = 2x - 3", "topic": "Hàm số bậc nhất"},
